From 51a37e9dbcb89770fbb65516edb8d04ad5b4b610 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:35:35 +0100
Subject: [PATCH] AppletPopup: don't remember a size the popup picked by itself

The popup saved its size whenever it closed, so a size it only grew to
for a temporary minimum, like the clock's events pane, stuck for good.
Now only sizes that differ from the automatic one are remembered.

BUG: 465063
---
 src/plasmaquick/appletpopup.cpp | 35 ++++++++++++++++++++++++---------
 src/plasmaquick/appletpopup.h   |  1 +
 2 files changed, 27 insertions(+), 9 deletions(-)

diff --git a/src/plasmaquick/appletpopup.cpp b/src/plasmaquick/appletpopup.cpp
index edb9c6885..64eaa4e16 100644
--- a/src/plasmaquick/appletpopup.cpp
+++ b/src/plasmaquick/appletpopup.cpp
@@ -142,8 +142,15 @@ void AppletPopup::hideEvent(QHideEvent *event)
         KConfigGroup config = m_appletInterface->applet()->config();
         // save size without margins, so we're robust against theme changes
         const QSize popupSize = size().shrunkBy(padding());
-        config.writeEntry("popupWidth", popupSize.width());
-        config.writeEntry("popupHeight", popupSize.height());
+        // Only remember a size the popup would not pick by itself, so that it can
+        // follow its content again, e.g. shrink back once a minimum size goes away
+        if (!m_sizeExplicitlySetFromConfig && size() == implicitPopupSize()) {
+            config.deleteEntry("popupWidth");
+            config.deleteEntry("popupHeight");
+        } else {
+            config.writeEntry("popupWidth", popupSize.width());
+            config.writeEntry("popupHeight", popupSize.height());
+        }
         config.sync();
     }

@@ -175,6 +182,10 @@ void AppletPopup::updateMinSize()
         return;
     }
     setMinimumSize(m_layoutChangedProxy->minimumSize().grownBy(padding()));
+    if (!m_sizeExplicitlySetFromConfig) {
+        updateSize();
+        return;
+    }
     // SetMinimumsize doesn't work since
     // https://codereview.qt-project.org/c/qt/qtwayland/+/527831
     // which fixes and conforms to the wayland protocol specification.
@@ -208,13 +219,7 @@ void AppletPopup::updateSize()
     if (!m_layoutChangedProxy) {
         return;
     }
-    const QSize wantedSize = m_layoutChangedProxy->implicitSize().grownBy(padding());
-
-    // NOTE: not using std::clamp as it might assert due to (possible) malformed values, sich as min > max
-    QSize size = {
-        std::min(std::max(minimumSize().width(), wantedSize.width()), maximumSize().width()),
-        std::min(std::max(minimumSize().height(), wantedSize.height()), maximumSize().height())
-    };
+    const QSize size = implicitPopupSize();

     if (!size.isEmpty()) {
         resize(size);
@@ -223,6 +228,18 @@ void AppletPopup::updateSize()
     }
 }

+QSize AppletPopup::implicitPopupSize() const
+{
+    if (!m_layoutChangedProxy) {
+        return QSize();
+    }
+    const QSize wantedSize = m_layoutChangedProxy->implicitSize().grownBy(padding());
+
+    // NOTE: not using std::clamp as it might assert due to (possible) malformed values, sich as min > max
+    return {std::min(std::max(minimumSize().width(), wantedSize.width()), maximumSize().width()),
+            std::min(std::max(minimumSize().height(), wantedSize.height()), maximumSize().height())};
+}
+
 LayoutChangedProxy::LayoutChangedProxy(QQuickItem *item)
     : m_item(item)
 {
diff --git a/src/plasmaquick/appletpopup.h b/src/plasmaquick/appletpopup.h
index 2b7c5888b..939c5c14c 100644
--- a/src/plasmaquick/appletpopup.h
+++ b/src/plasmaquick/appletpopup.h
@@ -56,6 +56,7 @@ private:
     void updateMinSize();
     void updateMaxSize();
     void updateSize();
+    QSize implicitPopupSize() const;

     QPointer<AppletQuickItem> m_appletInterface;
     QPointer<QScreen> m_oldScreen;
